import { parseBoardCode } from '../deck.ts';
import { MOVES_MAX } from '../game.ts';
import { decodeSnapshot } from '../snapshot.ts';

export interface Result {
  moves: number;
  elapsedMs: number;
}
export interface Match {
  players: [number, number];
  code: string;
  results: [Result | null, Result | null];
  winner: number | null;
}
export type Phase = 'ready' | 'playing' | 'turnDone' | 'matchDone' | 'complete';
export interface Tournament {
  names: string[];
  matches: Match[];
  phase: Phase;
  snapshot: string | null;
}

export function normalizeName(name: string): string {
  return name.trim().replace(/\s+/gu, ' ').normalize('NFC');
}
export function nameError(names: string[]): string {
  if (names.some((name) => Array.from(name).length < 2 || Array.from(name).length > 20))
    return 'Use 2 to 20 characters.';
  if (new Set(names.map((name) => name.toLowerCase())).size !== names.length)
    return 'Each name must be different.';
  return '';
}
export function opening(count: number): [number, number][] {
  return count === 4
    ? [
        [0, 3],
        [1, 2],
      ]
    : [
        [0, 7],
        [3, 4],
        [2, 5],
        [1, 6],
      ];
}
export function roundSize(count: number, index: number): number {
  return count === 8 && index < 4 ? 4 : index < count - 2 ? 6 : 8;
}
export function roundName(count: number, index: number): string {
  return count === 8 && index < 4 ? 'Quarterfinal' : index < count - 2 ? 'Semifinal' : 'Final';
}
export function pairAt(names: string[], matches: Match[]): [number, number] {
  const index = matches.length;
  const first = opening(names.length);
  if (index < first.length) return first[index]!;
  const source = index === names.length - 2 ? (names.length === 8 ? 4 : 0) : (index - 4) * 2;
  return [matches[source]!.winner!, matches[source + 1]!.winner!];
}
export function winner(match: Match): number {
  const [a, b] = match.results as [Result, Result];
  return a.moves !== b.moves
    ? match.players[a.moves < b.moves ? 0 : 1]
    : a.elapsedMs !== b.elapsedMs
      ? match.players[a.elapsedMs < b.elapsedMs ? 0 : 1]
      : Math.min(...match.players);
}
export function newMatch(names: string[], matches: Match[], code: string): Match {
  return { players: pairAt(names, matches), code, results: [null, null], winner: null };
}

function object(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}
function keys(value: Record<string, unknown>, expected: string[]): string | null {
  return Object.keys(value).find((key) => !expected.includes(key)) ?? null;
}
export function encodeTournament(
  tournament: Tournament | null,
  drafts: string[],
  count: number,
): string {
  const sort = (_key: string, value: unknown): unknown =>
    object(value)
      ? Object.fromEntries(Object.entries(value).sort(([a], [b]) => a.localeCompare(b)))
      : value;
  return JSON.stringify(
    { format: 'neon-pairs/tournament', version: 1, tournament, drafts, count },
    sort,
    2,
  );
}
export function decodeTournament(
  text: string,
): { tournament: Tournament | null; drafts: string[]; count: number } | string {
  try {
    if (new TextEncoder().encode(text).length > 65536) return 'Invalid tournament.';
    const value: unknown = JSON.parse(text);
    if (!object(value)) return 'Invalid tournament.';
    let extra = keys(value, ['format', 'version', 'tournament', 'drafts', 'count']);
    if (extra) return `Unknown field: ${extra}.`;
    if (
      value.format !== 'neon-pairs/tournament' ||
      value.version !== 1 ||
      (value.count !== 4 && value.count !== 8) ||
      !Array.isArray(value.drafts) ||
      value.drafts.length !== 8 ||
      value.drafts.some((x: unknown) => typeof x !== 'string' || x.length > 1000)
    )
      return 'Invalid tournament.';
    const drafts = value.drafts as string[];
    if (value.tournament === null) return { tournament: null, drafts, count: value.count };
    const t = value.tournament;
    if (!object(t)) return 'Invalid tournament.';
    extra = keys(t, ['names', 'matches', 'phase', 'snapshot']);
    if (extra) return `Unknown field: ${extra}.`;
    if (
      !Array.isArray(t.names) ||
      (t.names.length !== 4 && t.names.length !== 8) ||
      t.names.some((x: unknown) => typeof x !== 'string' || normalizeName(x) !== x) ||
      nameError(t.names as string[]) ||
