      const match: Match = {
        players: raw.players as [number, number],
        code: raw.code,
        results: results as [Result | null, Result | null],
        winner: raw.winner as number | null,
      };
      if ((results[1] ? winner(match) : null) !== raw.winner) return 'Invalid tournament.';
      matches.push(match);
    }
    const last = matches.at(-1)!;
    const phase = t.phase as Phase;
    if (
      (phase === 'complete') !== (last.winner !== null && matches.length === names.length - 1) ||
